/** 
 * Returns the room corresponding to the server channel.
 * @return the room corresponding to the server channel
 */
protected ChatRoomIrcImpl findSystemRoom(){
  if (serverChatRoom == null) {
    try {
      serverChatRoom=new ChatRoomIrcImpl(ircProvider.getAccountID().getService(),ircProvider,true);
      this.fireLocalUserPresenceEvent(serverChatRoom,LocalUserChatRoomPresenceChangeEvent.LOCAL_USER_JOINED,"Connected to the server.");
    } catch (NullPointerException e) {
      // Handle the case where ircProvider or getAccountID() is null
      throw new IllegalStateException("IRC provider or account ID is not available", e);
    }
  }
  return serverChatRoom;
}
